package com.saludintegral.cita.model;
import jakarta.persistence.*;import java.time.*;@Entity @Table(name="cita") public class Cita{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_cita") public Long idCita;@Column(nullable=false)public LocalDate fecha;@Column(nullable=false)public LocalTime hora;@Column(name="id_paciente",nullable=false)public Long idPaciente;@Column(name="id_medico",nullable=false)public Long idMedico;@Column(length=300)public String motivo;@Enumerated(EnumType.STRING)@Column(length=20,nullable=false)public EstadoCita estado=EstadoCita.PROGRAMADA;}
